-- Exploration: Montréal landmark catalogue, PostGIS geofences, GPS-verified visits and the
-- camera → gallery workflow. Run after 006. Safe to run again (idempotent).
-- Then run 008_montreal_island_boundary.sql and 009_landmarks_seed.sql (generated by
-- backend/scripts/import_landmarks.py).
--
-- Design:
--   * PostGIS (schema `extensions`, Supabase's default) is the only judge of where a photo was
--     taken. The camera does NOT recognise anything: the shutter takes a one-shot GPS reading,
--     and the server checks it against each landmark's geofence.
--       TYPE A  circle:  ST_DWithin(landmark.location, fix, landmark.geofence_radius_m)
--       TYPE B  polygon: ST_Covers(landmark.geofence_polygon, fix)   (parks, campuses…)
--   * Everything is limited to the Island of Montréal (service_areas 'montreal-island'):
--     the catalogue, the checks and the gallery uploads made from the camera.
--   * The browser never writes a visit. explore_register_capture() re-validates the fix, then saves
--     the photo row and (first time only) the discovery in one transaction.
--   * Raw coordinates of a capture are NOT stored: only the landmark association, the reported
--     accuracy and the time. (Manual uploads from 006 keep their optional city pin, as before.)
--   * Recommendations are a separate system. landmark_recommendations is its integration point:
--     the recommender writes rows there; the map only reads a `recommended` flag. Nothing here
--     hides a landmark because it isn't recommended.
--   * Points are NOT awarded here (separate task). A visit only changes the visited state.
--   * GPS from a browser can be spoofed. Checks here (accuracy, freshness, capture/fix gap,
--     Montréal scope, rate limit, server-side geofences) are reasonable basics, not proof.

-- ---------------------------------------------------------------------------
-- PostGIS
-- ---------------------------------------------------------------------------

create schema if not exists extensions;
create extension if not exists postgis with schema extensions;

do $$
declare
  s text;
begin
  select n.nspname into s from pg_extension e join pg_namespace n on n.oid = e.extnamespace where e.extname = 'postgis';
  if s is distinct from 'extensions' then
    raise exception 'PostGIS is installed in schema "%" but this migration expects "extensions". In the dashboard: Database → Extensions → postgis, check its schema.', s;
  end if;
end;
$$;

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------

-- Geographic scope of the app. One row today: 'montreal-island' (008 loads the official boundary).
create table if not exists public.service_areas (
  id              text primary key,
  name            text not null,
  geom            extensions.geography(MultiPolygon, 4326) not null,
  source_name     text,
  source_url      text,
  source_license  text,
  updated_at      timestamptz not null default now()
);
create index if not exists service_areas_geom_gix on public.service_areas using gist (geom);

-- The catalogue. id is stable across re-imports (upserts key on source_name + source_record_id).
create table if not exists public.landmarks (
  id                 uuid primary key default gen_random_uuid(),
  slug               text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) <= 120),
  name               text not null check (char_length(btrim(name)) between 1 and 200),
  description        text check (char_length(description) <= 4000),
  category           text not null check (category in ('landmark', 'museum', 'park', 'historic', 'architecture', 'religious',
                                                       'culture', 'viewpoint', 'market', 'public-art', 'campus', 'other')),
  latitude           double precision not null check (latitude between -90 and 90),
  longitude          double precision not null check (longitude between -180 and 180),
  -- Kept in sync with latitude/longitude by the trigger below (WGS84 / EPSG:4326).
  location           extensions.geography(Point, 4326),
  -- TYPE A: circle around `location`. Used when there is no polygon.
  geofence_radius_m  integer not null default 60 check (geofence_radius_m between 10 and 2000),
  -- TYPE B: the area itself (from open data only, never drawn by hand from imagery).
  geofence_polygon   extensions.geography(MultiPolygon, 4326),
  -- Optional, for later clustering/aggregation. Never used to decide a visit.
  h3_index           text,
  address            text,
  neighbourhood      text,
  source_name        text not null,
  source_url         text,
  source_license     text not null,
  source_record_id   text not null,
  -- Uncertain provenance/licence or outside the island: kept for review, not silently trusted.
  needs_review       boolean not null default false,
  review_note        text,
  is_active          boolean not null default true,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  unique (source_name, source_record_id)
);
create index if not exists landmarks_location_gix on public.landmarks using gist (location);
create index if not exists landmarks_polygon_gix on public.landmarks using gist (geofence_polygon);
create index if not exists landmarks_active_idx on public.landmarks (is_active);

-- Tunable thresholds (one row). Change with an UPDATE in the SQL editor after testing on phones.
create table if not exists public.explore_settings (
  id                      boolean primary key default true check (id),
  -- Reported GPS accuracy must be at most this (metres).
  max_accuracy_m          real    not null default 50,
  -- The fix must be at most this old when checked (seconds; generous for phone clock skew).
  max_position_age_s      integer not null default 120,
  -- …and at most this old when the photo is registered (includes upload time on mobile data).
  max_register_age_s      integer not null default 900,
  -- Photo capture time and fix time must be this close (seconds, both from the phone's clock).
  max_capture_gap_s       integer not null default 30,
  -- Two circle matches closer than this to each other (metres) are ambiguous: the user picks.
  ambiguity_margin_m      real    not null default 15,
  -- Basic abuse limit: camera captures per profile per 10 minutes.
  max_captures_per_10min  integer not null default 30,
  -- Allowed device-clock lead over the server (seconds).
  max_clock_skew_s        integer not null default 120
);
insert into public.explore_settings (id) values (true) on conflict (id) do nothing;

-- One discovery per person and landmark. More photos of the same place just add gallery rows.
create table if not exists public.user_landmark_discoveries (
  id                uuid primary key default gen_random_uuid(),
  profile_id        uuid not null references public.profiles(id) on delete cascade,
  landmark_id       uuid not null references public.landmarks(id) on delete cascade,
  first_visited_at  timestamptz not null,
  first_photo_id    uuid references public.photos(id) on delete set null,
  created_at        timestamptz not null default now(),
  unique (profile_id, landmark_id)
);
create index if not exists user_landmark_discoveries_profile_idx on public.user_landmark_discoveries (profile_id, first_visited_at desc);

-- Integration point for the recommendation system (Questionnaire B → places). This migration does
-- not fill it; the recommender (service role or its own function) does. Read-only for the map.
create table if not exists public.landmark_recommendations (
  profile_id   uuid not null references public.profiles(id) on delete cascade,
  landmark_id  uuid not null references public.landmarks(id) on delete cascade,
  score        real,
  reason       text,
  source       text not null default 'questionnaire-b',
  updated_at   timestamptz not null default now(),
  primary key (profile_id, landmark_id)
);

-- Gallery photos (006) gain the landmark association.
alter table public.photos add column if not exists landmark_id uuid references public.landmarks(id) on delete set null;
alter table public.photos add column if not exists association_status text;
alter table public.photos add column if not exists gps_accuracy_m real;
alter table public.photos add column if not exists file_size_bytes integer;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'photos_association_status_check') then
    alter table public.photos add constraint photos_association_status_check
      check (association_status is null or association_status in ('landmark_visit', 'montreal_unassigned'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'photos_gps_accuracy_check') then
    alter table public.photos add constraint photos_gps_accuracy_check check (gps_accuracy_m is null or gps_accuracy_m >= 0);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'photos_file_size_check') then
    alter table public.photos add constraint photos_file_size_check
      check (file_size_bytes is null or file_size_bytes between 1 and 8388608);
  end if;
end;
$$;
create index if not exists photos_landmark_idx on public.photos (profile_id, landmark_id) where landmark_id is not null;
create index if not exists photos_capture_rate_idx on public.photos (profile_id, created_at) where association_status is not null;

-- ---------------------------------------------------------------------------
-- Row level security
--   * Catalogue (landmarks, service_areas): public read, no client writes. Managing landmarks is
--     done by the import script / SQL editor (service role), as for hunts today.
--   * Discoveries, recommendations, settings: no direct access; only through the functions below,
--     which always act for auth.uid()'s own profile.
-- ---------------------------------------------------------------------------

alter table public.landmarks enable row level security;
alter table public.service_areas enable row level security;
alter table public.user_landmark_discoveries enable row level security;
alter table public.landmark_recommendations enable row level security;
alter table public.explore_settings enable row level security;

revoke all on public.landmarks, public.service_areas, public.user_landmark_discoveries,
              public.landmark_recommendations, public.explore_settings from anon, authenticated;
grant select on public.landmarks, public.service_areas to anon, authenticated;

drop policy if exists "landmarks: public read of active" on public.landmarks;
create policy "landmarks: public read of active" on public.landmarks for select to anon, authenticated using (is_active);
drop policy if exists "service areas: public read" on public.service_areas;
create policy "service areas: public read" on public.service_areas for select to anon, authenticated using (true);

-- ---------------------------------------------------------------------------
-- Landmark upkeep: location from lat/lng, updated_at, island scope.
-- ---------------------------------------------------------------------------

create or replace function public.landmarks_before_write() returns trigger
language plpgsql set search_path = public, extensions as $$
declare
  area extensions.geography;
begin
  new.location := extensions.st_setsrid(extensions.st_makepoint(new.longitude, new.latitude), 4326)::extensions.geography;
  new.updated_at := now();
  -- Outside the island (when the boundary is loaded): keep it, but inactive and flagged.
  select geom into area from service_areas where id = 'montreal-island';
  if area is not null and not extensions.st_covers(area, new.location) then
    new.is_active := false;
    new.needs_review := true;
    new.review_note := coalesce(nullif(new.review_note, '') || '; ', '') || 'outside Montréal Island boundary';
  end if;
  return new;
end;
$$;

drop trigger if exists landmarks_before_write on public.landmarks;
create trigger landmarks_before_write before insert or update on public.landmarks
  for each row execute function public.landmarks_before_write();

-- Re-applies the island rule to every landmark (run after replacing the boundary).
create or replace function public.explore_recheck_scope() returns integer
language plpgsql security definer set search_path = public, extensions as $$
declare
  n integer;
begin
  update landmarks l
     set is_active = false,
         needs_review = true,
         review_note = coalesce(nullif(review_note, '') || '; ', '') || 'outside Montréal Island boundary'
   where l.is_active
     and exists (select 1 from service_areas a where a.id = 'montreal-island' and not extensions.st_covers(a.geom, l.location));
  get diagnostics n = row_count;
  return n;
end;
$$;

-- ---------------------------------------------------------------------------
-- Internal helpers
-- ---------------------------------------------------------------------------

-- The caller's profile id (auth.uid() → profiles.auth_user_id), or null.
create or replace function public.explore_my_profile_id() returns uuid
language sql stable security definer set search_path = public as $$
  select id from profiles where auth_user_id = auth.uid() and auth.uid() is not null
$$;

-- Evaluates one GPS fix. Pure read. Returns the same JSON shape explore_check_location returns.
-- p_max_age_s: freshness allowed relative to the server clock (checks vs. registration).
create or replace function public.explore_evaluate(
  p_profile_id   uuid,
  p_lat          double precision,
  p_lng          double precision,
  p_accuracy_m   double precision,
  p_position_at  timestamptz,
  p_captured_at  timestamptz,
  p_max_age_s    integer
) returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  cfg        explore_settings;
  pt         extensions.geography;
  area       extensions.geography;
  limits     jsonb;
  cands      jsonb;
  n          integer;
  first_c    jsonb;
  second_c   jsonb;
  resolved   uuid;
  ambiguous  boolean := false;
  recent     integer;

  -- Builds the result object.
  function_result jsonb;
begin
  select * into cfg from explore_settings where id;
  limits := jsonb_build_object('max_accuracy_m', cfg.max_accuracy_m, 'max_position_age_s', cfg.max_position_age_s,
                               'max_capture_gap_s', cfg.max_capture_gap_s);

  if p_lat is null or p_lng is null or p_lat not between -90 and 90 or p_lng not between -180 and 180
     or p_accuracy_m is null or p_accuracy_m < 0 or p_position_at is null or p_captured_at is null then
    raise exception 'Invalid location reading' using errcode = '22023';
  end if;

  -- 1. Rate limit (camera captures in the last 10 minutes).
  select count(*) into recent from photos
   where profile_id = p_profile_id and association_status is not null and created_at > now() - interval '10 minutes';
  if recent >= cfg.max_captures_per_10min then
    return jsonb_build_object('status', 'rate_limited', 'reason', 'rate_limited',
      'message', 'You’ve taken a lot of photos in a few minutes. Take a short break, then try again.',
      'candidates', '[]'::jsonb, 'resolved_landmark_id', null, 'ambiguous', false, 'limits', limits);
  end if;

  -- 2. Accuracy.
  if p_accuracy_m > cfg.max_accuracy_m then
    return jsonb_build_object('status', 'retry', 'reason', 'poor_accuracy',
      'message', format('Your GPS is only accurate to about %s m (we need %s m or better). Step into the open and try again.',
                        round(p_accuracy_m::numeric), round(cfg.max_accuracy_m::numeric)),
      'candidates', '[]'::jsonb, 'resolved_landmark_id', null, 'ambiguous', false, 'limits', limits);
  end if;

  -- 3. Timing: the reading's own timestamp, not the upload time.
  if p_position_at > now() + make_interval(secs => cfg.max_clock_skew_s)
     or p_captured_at > now() + make_interval(secs => cfg.max_clock_skew_s) then
    return jsonb_build_object('status', 'retry', 'reason', 'future_timestamp',
      'message', 'Your phone’s clock looks off. Check its date and time, then try again.',
      'candidates', '[]'::jsonb, 'resolved_landmark_id', null, 'ambiguous', false, 'limits', limits);
  end if;
  if abs(extract(epoch from (p_captured_at - p_position_at))) > cfg.max_capture_gap_s then
    return jsonb_build_object('status', 'retry', 'reason', 'capture_gap',
      'message', 'The location reading wasn’t taken at the same time as the photo. Get a fresh reading.',
      'candidates', '[]'::jsonb, 'resolved_landmark_id', null, 'ambiguous', false, 'limits', limits);
  end if;
  if p_position_at < now() - make_interval(secs => p_max_age_s) then
    return jsonb_build_object('status', 'retry', 'reason', 'stale_position',
      'message', 'That location reading is too old. Get a fresh one.',
      'candidates', '[]'::jsonb, 'resolved_landmark_id', null, 'ambiguous', false, 'limits', limits);
  end if;

  pt := extensions.st_setsrid(extensions.st_makepoint(p_lng, p_lat), 4326)::extensions.geography;

  -- 4. Montréal Island only.
  select geom into area from service_areas where id = 'montreal-island';
  if area is null then
    raise exception 'The Montréal boundary isn’t loaded yet (run 008_montreal_island_boundary.sql)' using errcode = '55000';
  end if;
  if not extensions.st_covers(area, pt) then
    return jsonb_build_object('status', 'outside_area', 'reason', 'outside_area',
      'message', 'This photo was taken outside the Island of Montréal. MIGO’s gallery only covers Montréal for now, so it wasn’t saved.',
      'candidates', '[]'::jsonb, 'resolved_landmark_id', null, 'ambiguous', false, 'limits', limits);
  end if;

  -- 5–6. Candidate geofences. Circles first (most specific), nearest first; then areas, smallest
  -- first (a garden inside a park beats the park). The 2 km pre-filter uses the spatial index.
  select coalesce(jsonb_agg(c order by c.rank_group, c.sort_key, c.name, c.id), '[]'::jsonb), count(*)
    into cands, n
    from (
      select l.id, l.name, l.category,
             round(extensions.st_distance(l.location, pt)::numeric, 1)::double precision as distance_m,
             case when l.geofence_polygon is null then 'radius' else 'polygon' end as match,
             exists (select 1 from user_landmark_discoveries d where d.profile_id = p_profile_id and d.landmark_id = l.id) as visited,
             case when l.geofence_polygon is null then 0 else 1 end as rank_group,
             case when l.geofence_polygon is null then extensions.st_distance(l.location, pt)
                  else extensions.st_area(l.geofence_polygon) end as sort_key
        from landmarks l
       where l.is_active
         and (
           (l.geofence_polygon is null
             and extensions.st_dwithin(l.location, pt, 2000)
             and extensions.st_dwithin(l.location, pt, l.geofence_radius_m))
           or (l.geofence_polygon is not null and extensions.st_covers(l.geofence_polygon, pt))
         )
       order by rank_group, sort_key
       limit 10
    ) c;

  -- 7. Deterministic resolution: one candidate, or a clear winner. Two circles within the margin
  -- of each other are ambiguous: the user picks (the photo still gets at most one landmark).
  if n >= 1 then
    first_c := cands -> 0;
    second_c := cands -> 1;
    if second_c is not null and first_c ->> 'match' = 'radius' and second_c ->> 'match' = 'radius'
       and (second_c ->> 'distance_m')::double precision - (first_c ->> 'distance_m')::double precision < cfg.ambiguity_margin_m then
      ambiguous := true;
    else
      resolved := (first_c ->> 'id')::uuid;
    end if;
  end if;

  function_result := jsonb_build_object(
    'status', 'ok',
    'reason', null,
    'message', case
      when n = 0 then 'No MIGO place right here. The photo will be saved as a Montréal memory.'
      when ambiguous then 'You’re near several places. Pick the one this photo is of.'
      else format('You’re at %s.', first_c ->> 'name') end,
    'candidates', (select coalesce(jsonb_agg(e.v - 'rank_group' - 'sort_key' order by e.i), '[]'::jsonb)
                     from jsonb_array_elements(cands) with ordinality as e(v, i)),
    'resolved_landmark_id', resolved,
    'ambiguous', ambiguous,
    'limits', limits);
  return function_result;
end;
$$;

-- ---------------------------------------------------------------------------
-- API functions
-- ---------------------------------------------------------------------------

-- Map: active landmarks in a viewport, with the caller's visited/recommended flags (false when
-- signed out). Never filtered by recommendations. Always a JSON array.
create or replace function public.landmarks_in_view(
  p_west double precision, p_south double precision, p_east double precision, p_north double precision,
  p_limit integer default 3000
) returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  me uuid := explore_my_profile_id();
  box extensions.geography;
begin
  if p_west is null or p_south is null or p_east is null or p_north is null
     or p_south > p_north or p_south < -90 or p_north > 90 then
    raise exception 'Invalid map bounds' using errcode = '22023';
  end if;
  -- Viewports crossing the antimeridian aren't needed for Montréal: clamp to a normal box.
  box := extensions.st_makeenvelope(greatest(-180, least(p_west, p_east)), p_south, least(180, greatest(p_west, p_east)), p_north, 4326)::extensions.geography;
  return coalesce((
    select jsonb_agg(row_json order by recommended desc, name)
      from (
        select l.name,
               (r.landmark_id is not null) as recommended,
               jsonb_build_object(
                 'id', l.id, 'slug', l.slug, 'name', l.name, 'category', l.category,
                 'lat', l.latitude, 'lng', l.longitude,
                 'geofence_radius_m', l.geofence_radius_m,
                 'has_polygon', l.geofence_polygon is not null,
                 'visited', d.landmark_id is not null,
                 'visited_at', d.first_visited_at,
                 'recommended', r.landmark_id is not null) as row_json
          from landmarks l
          left join user_landmark_discoveries d on d.landmark_id = l.id and d.profile_id = me
          left join landmark_recommendations r on r.landmark_id = l.id and r.profile_id = me
         where l.is_active and l.location && box
         order by (r.landmark_id is not null) desc, l.name
         limit least(greatest(coalesce(p_limit, 3000), 1), 5000)
      ) x), '[]'::jsonb);
end;
$$;

-- One landmark with its polygon (GeoJSON) and attribution. Null when unknown or inactive.
create or replace function public.landmark_get(p_id_or_slug text) returns jsonb
language sql stable security definer set search_path = public, extensions as $$
  select jsonb_build_object(
           'id', l.id, 'slug', l.slug, 'name', l.name, 'category', l.category,
           'lat', l.latitude, 'lng', l.longitude,
           'geofence_radius_m', l.geofence_radius_m,
           'has_polygon', l.geofence_polygon is not null,
           'visited', d.landmark_id is not null,
           'visited_at', d.first_visited_at,
           'recommended', r.landmark_id is not null,
           'description', l.description, 'address', l.address, 'neighbourhood', l.neighbourhood,
           'polygon', case when l.geofence_polygon is null then null
                           else extensions.st_asgeojson(l.geofence_polygon, 6)::jsonb end,
           'source_name', l.source_name, 'source_url', l.source_url,
           'source_license', l.source_license, 'source_record_id', l.source_record_id)
    from landmarks l
    left join user_landmark_discoveries d on d.landmark_id = l.id and d.profile_id = explore_my_profile_id()
    left join landmark_recommendations r on r.landmark_id = l.id and r.profile_id = explore_my_profile_id()
   where l.is_active and (l.id::text = p_id_or_slug or l.slug = lower(p_id_or_slug))
   limit 1
$$;

-- Camera pre-check, before anything is uploaded. Read-only. Signed-in only.
create or replace function public.explore_check_location(
  p_lat double precision, p_lng double precision, p_accuracy_m double precision,
  p_position_at timestamptz, p_captured_at timestamptz
) returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  me uuid := explore_my_profile_id();
begin
  if me is null then
    raise exception 'Sign in to take MIGO photos' using errcode = '42501';
  end if;
  return explore_evaluate(me, p_lat, p_lng, p_accuracy_m, p_position_at, p_captured_at,
                          (select max_position_age_s from explore_settings where id));
end;
$$;

-- Registers an uploaded camera photo. Re-validates the fix (the server is the source of truth),
-- then in one transaction saves the photo and, for a landmark, the first visit (unique per
-- person + landmark; repeat visits only add photos). Errors (the app then deletes the file):
--   42501 not signed in / not your folder, 22023 bad input or place not near you,
--   P0002 file not uploaded, P0001 with hint retry | outside_area | rate_limited | needs_choice.
create or replace function public.explore_register_capture(
  p_storage_path    text,
  p_lat             double precision,
  p_lng             double precision,
  p_accuracy_m      double precision,
  p_position_at     timestamptz,
  p_captured_at     timestamptz,
  p_landmark_id     uuid default null,
  p_width           integer default null,
  p_height          integer default null,
  p_file_size_bytes integer default null
) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  uid       uuid := auth.uid();
  me        uuid := explore_my_profile_id();
  cfg       explore_settings;
  ev        jsonb;
  chosen    uuid;
  lm        landmarks;
  ph        photos;
  disc      user_landmark_discoveries;
  is_new    boolean := false;
  uploaded  boolean;
begin
  if uid is null or me is null then
    raise exception 'Sign in to take MIGO photos' using errcode = '42501';
  end if;
  if p_storage_path is null or p_storage_path !~ ('^' || uid::text || '/[A-Za-z0-9_-]{1,100}\.jpg$') then
    raise exception 'Photos must be stored in your own folder as <id>.jpg' using errcode = '42501';
  end if;
  select * into cfg from explore_settings where id;

  -- The file must really be in the bucket (two-phase upload). Skipped where there's no storage schema.
  if to_regclass('storage.objects') is not null then
    execute 'select exists (select 1 from storage.objects where bucket_id = $1 and name = $2)'
       into uploaded using 'gallery', p_storage_path;
    if not uploaded then
      raise exception 'Upload the photo before registering it' using errcode = 'P0002';
    end if;
  end if;

  -- Serialise this person's registrations, so the rate limit and first-visit logic can't race.
  perform pg_advisory_xact_lock(hashtext('explore_register:' || me::text));

  ev := explore_evaluate(me, p_lat, p_lng, p_accuracy_m, p_position_at, p_captured_at, cfg.max_register_age_s);
  if ev ->> 'status' <> 'ok' then
    raise exception '%', ev ->> 'message' using errcode = 'P0001',
      hint = case ev ->> 'status' when 'retry' then 'retry' else ev ->> 'status' end;
  end if;

  if p_landmark_id is not null then
    if not exists (select 1 from jsonb_array_elements(ev -> 'candidates') c where (c ->> 'id')::uuid = p_landmark_id) then
      raise exception 'That place isn’t close enough to where the photo was taken' using errcode = '22023';
    end if;
    chosen := p_landmark_id;
  elsif (ev ->> 'ambiguous')::boolean then
    raise exception 'Pick which place this photo is of' using errcode = 'P0001', hint = 'needs_choice';
  else
    chosen := nullif(ev ->> 'resolved_landmark_id', '')::uuid;
  end if;

  begin
    insert into photos (profile_id, storage_path, city_name, country, country_code, landmark_id, association_status,
                        gps_accuracy_m, file_size_bytes, taken_at, width, height)
    values (me, p_storage_path, 'Montréal', 'Canada', 'CA', chosen,
            case when chosen is null then 'montreal_unassigned' else 'landmark_visit' end,
            round(p_accuracy_m::numeric, 1), p_file_size_bytes, least(p_captured_at, now()), p_width, p_height)
    returning * into ph;
  exception
    when unique_violation then
      raise exception 'This photo is already saved' using errcode = '23505';
    when check_violation then
      raise exception 'Invalid photo details: %', sqlerrm using errcode = '22023';
  end;

  if chosen is not null then
    select * into lm from landmarks where id = chosen;
    insert into user_landmark_discoveries (profile_id, landmark_id, first_visited_at, first_photo_id)
    values (me, chosen, ph.taken_at, ph.id)
    on conflict (profile_id, landmark_id) do nothing
    returning * into disc;
    is_new := disc.id is not null;
    if not is_new then
      select * into disc from user_landmark_discoveries where profile_id = me and landmark_id = chosen;
    end if;
  end if;

  return jsonb_build_object(
    'photo_id', ph.id,
    'association_status', ph.association_status,
    'landmark', case when chosen is null then null else jsonb_build_object('id', lm.id, 'name', lm.name, 'slug', lm.slug) end,
    'new_discovery', is_new,
    'first_visited_at', disc.first_visited_at);
end;
$$;

-- The caller's visited landmarks, newest first, with how many photos they have of each.
create or replace function public.explore_my_discoveries() returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'landmark_id', l.id, 'name', l.name, 'slug', l.slug, 'category', l.category,
           'first_visited_at', d.first_visited_at, 'first_photo_id', d.first_photo_id,
           'photo_count', (select count(*) from photos p where p.profile_id = d.profile_id and p.landmark_id = d.landmark_id))
         order by d.first_visited_at desc, l.name), '[]'::jsonb)
    from user_landmark_discoveries d
    join landmarks l on l.id = d.landmark_id
   where d.profile_id = explore_my_profile_id()
$$;

-- ---------------------------------------------------------------------------
-- Gallery (006) now returns the landmark association too.
-- ---------------------------------------------------------------------------

create or replace function public.gallery_photo_json(p photos) returns jsonb
language sql immutable as $$
  select jsonb_build_object(
    'id', p.id,
    'storage_path', p.storage_path,
    'city_name', p.city_name,
    'country', p.country,
    'country_code', p.country_code,
    'lat', p.lat,
    'lng', p.lng,
    'place_id', p.place_id,
    'caption', p.caption,
    'quest_id', p.quest_id,
    'hunt_id', p.hunt_id,
    'taken_at', p.taken_at,
    'width', p.width,
    'height', p.height,
    'created_at', p.created_at,
    'landmark_id', p.landmark_id,
    'association_status', p.association_status,
    'gps_accuracy_m', p.gps_accuracy_m,
    'file_size_bytes', p.file_size_bytes)
$$;

create or replace function public.gallery_list(p_profile_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform migo_assert_owner(p_profile_id);
  return coalesce(
    (select jsonb_agg(gallery_photo_json(p) || jsonb_build_object('landmark_name', l.name, 'landmark_slug', l.slug)
                      order by p.taken_at desc, p.created_at desc, p.id)
       from photos p
       left join landmarks l on l.id = p.landmark_id
      where p.profile_id = p_profile_id),
    '[]'::jsonb);
end;
$$;

-- ---------------------------------------------------------------------------
-- Storage: the 'gallery' bucket becomes PRIVATE. The owner-folder policies from 006 stay; the app
-- shows photos through short-lived signed URLs (which need the "read own folder" policy).
-- ---------------------------------------------------------------------------

do $$
begin
  if to_regclass('storage.buckets') is null then
    raise notice 'No storage schema here: skipped making the gallery bucket private (fine for local tests)';
    return;
  end if;
  execute $q$ update storage.buckets set public = false where id = 'gallery' $q$;
end;
$$;

-- ---------------------------------------------------------------------------
-- Grants. Supabase grants new functions to everyone by default: revoke, then grant what's needed.
-- ---------------------------------------------------------------------------

revoke execute on function public.landmarks_before_write() from public, anon, authenticated;
revoke execute on function public.explore_recheck_scope() from public, anon, authenticated;
revoke execute on function public.explore_my_profile_id() from public, anon, authenticated;
revoke execute on function public.explore_evaluate(uuid, double precision, double precision, double precision, timestamptz, timestamptz, integer) from public, anon, authenticated;
revoke execute on function public.gallery_photo_json(photos) from public, anon, authenticated;

revoke execute on function public.landmarks_in_view(double precision, double precision, double precision, double precision, integer) from public;
revoke execute on function public.landmark_get(text) from public;
revoke execute on function public.explore_check_location(double precision, double precision, double precision, timestamptz, timestamptz) from public, anon;
revoke execute on function public.explore_register_capture(text, double precision, double precision, double precision, timestamptz, timestamptz, uuid, integer, integer, integer) from public, anon;
revoke execute on function public.explore_my_discoveries() from public, anon;

grant execute on function public.landmarks_in_view(double precision, double precision, double precision, double precision, integer) to anon, authenticated;
grant execute on function public.landmark_get(text) to anon, authenticated;
grant execute on function public.explore_check_location(double precision, double precision, double precision, timestamptz, timestamptz) to authenticated;
grant execute on function public.explore_register_capture(text, double precision, double precision, double precision, timestamptz, timestamptz, uuid, integer, integer, integer) to authenticated;
grant execute on function public.explore_my_discoveries() to authenticated;
grant execute on function public.gallery_list(uuid) to authenticated;

-- PostgREST: pick up the new functions now.
notify pgrst, 'reload schema';
